// Extract message data from WhatsApp POST payload
const body = $input.first().json.body;

// Validate WhatsApp message structure
if (
  body.object !== 'whatsapp_business_account' ||
  !body.entry?.[0]?.changes?.[0]?.value?.messages?.[0]
) {
  return [{ json: { skip: true, reason: 'Not a valid WhatsApp message event' } }];
}

const change = body.entry[0].changes[0].value;
const message = change.messages[0];

if (!message.text?.body) {
  return [{ json: { skip: true, reason: 'Non-text message (image/audio/etc)' } }];
}

const fromNumber = message.from;
const messageText = message.text.body;
const timestamp = new Date(parseInt(message.timestamp) * 1000).toISOString();
const messageId = message.id;
const profileName = change.contacts?.[0]?.profile?.name || 'Unknown';

console.log(`[n8n] 📩 Message from ${fromNumber} (${profileName}): "${messageText}"`);

return [{
  json: {
    skip: false,
    from_number: fromNumber,
    message: messageText,
    timestamp,
    message_id: messageId,
    profile_name: profileName
  }
}];

