// Parse Groq response and build final ingest payload
const groqResponse = $input.first().json;
const prevData = $('Extract Message').first().json;

let structuredJson;
try {
  const content = groqResponse.choices[0].message.content;
  structuredJson = typeof content === 'string' ? JSON.parse(content) : content;
  // Patch in accurate metadata
  structuredJson.metadata = {
    ...structuredJson.metadata,
    model: 'llama-3.3-70b-versatile',
    processed_at: new Date().toISOString(),
    processed_by: 'n8n'
  };
} catch (e) {
  structuredJson = {
    intent: 'parse_error',
    entities: {},
    response: 'Could not parse LLM response.',
    sentiment: 'neutral',
    confidence: 0,
    language: 'en',
    suggested_actions: [],
    category: 'error',
    priority: 'low',
    metadata: {
      error: e.message,
      raw: groqResponse.choices?.[0]?.message?.content,
      model: 'llama-3.3-70b-versatile',
      processed_at: new Date().toISOString(),
      processed_by: 'n8n'
    }
  };
}

console.log(`[n8n] ✅ Intent: ${structuredJson.intent} | Confidence: ${structuredJson.confidence}`);

return [{
  json: {
    from_number: prevData.from_number,
    message: prevData.message,
    timestamp: prevData.timestamp,
    profile_name: prevData.profile_name,
    structured_json: structuredJson
  }
}];
